use serde_json::{Value, json};

pub fn solve(input: Value) -> Value {
    if let Some(Value::Object(obj)) = input.as_object() {
        if let (Some(Value::Array(values)), Some(Value::Number(size))) = (obj.get("values"), obj.get("size")) {
            if let Some(size) = size.as_i64() {
                if size > 0 && values.len() <= 64 {
                    let mut result = Vec::new();
                    let mut iter = values.iter();
                    while let Some(chunk) = iter.by_ref().take(size as usize).cloned().collect::<Vec<_>>() {
                        result.push(Value::Array(chunk));
                    }
                    return Value::Array(result);
                }
            }
        }
    }
    Value::Null
}
